  1	import React, { useState } from 'react';
  2	import { LATEST_EXCHANGE_ID } from './ConversationTurns';
  3	
  4	interface Props {
  5	  onAsk: (question: string) => void;
  6	  /** True while an answer is pending; submissions are ignored until it settles. */
  7	  busy: boolean;
  8	  /** True when there is at least one answered exchange to jump to. */
  9	  canJumpToLatest: boolean;
 10	}
 11	
 12	const visuallyHidden: React.CSSProperties = {
 13	  position: 'absolute',
 14	  width: '1px',
 15	  height: '1px',
 16	  overflow: 'hidden',
 17	  clip: 'rect(0 0 0 0)',
 18	  whiteSpace: 'nowrap',
 19	};
 20	
 21	export function QuestionPanel({ onAsk, busy, canJumpToLatest }: Props) {
 22	  const [question, setQuestion] = useState('');
 23	  const [jumpFocused, setJumpFocused] = useState(false);
 24	
 25	  // Moves focus to the newest exchange, so the next Tab reaches its citations
 26	  // without walking through every earlier exchange.
 27	  const jumpToLatest = () => {
 28	    document.getElementById(LATEST_EXCHANGE_ID)?.focus();
 29	  };
 30	
 31	  const handleKeyDown = (e: React.KeyboardEvent<HTMLInputElement>) => {
 32	    // Alt+ArrowUp from the input is a shortcut for the same jump.
 33	    if (e.altKey && e.key === 'ArrowUp' && canJumpToLatest) {
 34	      e.preventDefault();
 35	      jumpToLatest();
 36	    }
 37	  };
 38	
 39	  const handleSubmit = (e: React.FormEvent) => {
 40	    e.preventDefault();
 41	    if (busy || !question.trim()) return;
 42	    onAsk(question.trim());
 43	    setQuestion('');
 44	  };
 45	
 46	  return (
 47	    <form
 48	      onSubmit={handleSubmit}
 49	      aria-label="Ask a question"
 50	      style={{
 51	        display: 'flex',
 52	        padding: '12px 20px',
 53	        borderTop: '1px solid #0f3460',
 54	        background: '#16213e',
 55	      }}
 56	    >
 57	      <label htmlFor="question-input" style={visuallyHidden}>
 58	        Question about your documents
 59	      </label>
 60	      <input
 61	        id="question-input"
 62	        type="text"
 63	        value={question}
 64	        onChange={e => setQuestion(e.target.value)}
 65	        placeholder="Ask a question about your documents..."
 66	        autoComplete="off"
 67	        onKeyDown={handleKeyDown}
 68	        aria-keyshortcuts={canJumpToLatest ? 'Alt+ArrowUp' : undefined}
 69	        style={{
 70	          flex: 1,
 71	          minWidth: 0,
 72	          padding: '10px 14px',
 73	          background: '#1a1a2e',
 74	          color: '#e0e0e0',
 75	          border: '1px solid #0f3460',
 76	          borderRadius: '6px',
 77	          fontSize: '14px',
 78	        }}
 79	      />
 80	      {/* aria-disabled (not disabled) keeps focus on the button while an answer is pending. */}
 81	      <button
 82	        type="submit"
 83	        aria-disabled={busy}
 84	        style={{
 85	          marginLeft: '10px',
 86	          padding: '10px 20px',
 87	          background: '#533483',
 88	          color: '#fff',
 89	          border: 'none',
 90	          borderRadius: '6px',
 91	          cursor: busy ? 'progress' : 'pointer',
 92	          opacity: busy ? 0.6 : 1,
 93	          fontSize: '14px',
 94	          fontWeight: 500,
 95	        }}
 96	      >
 97	        {busy ? 'Answering…' : 'Ask'}
 98	      </button>
 99	      {/* Skip control: hidden until focused (Tab once past Ask). */}
100	      {canJumpToLatest && (
101	        <button
102	          type="button"
103	          onClick={jumpToLatest}
104	          onFocus={() => setJumpFocused(true)}
105	          onBlur={() => setJumpFocused(false)}
106	          style={jumpFocused ? {
107	            marginLeft: '10px',
108	            padding: '10px 14px',
109	            background: '#0f3460',
110	            color: '#e0e0e0',
111	            border: '1px solid #8888bb',
112	            borderRadius: '6px',
113	            cursor: 'pointer',
114	            fontSize: '13px',
115	            whiteSpace: 'nowrap',
116	          } : visuallyHidden}
117	        >
118	          Jump to latest answer
119	        </button>
120	      )}
121	    </form>
122	  );
123	}
  1	import { useEffect, useRef, useState } from 'react';
  2	import type { KeyboardEvent } from 'react';
  3	import { Citation, QAHistory } from '../../shared/types';
  4	import { AskError } from './conversation-format';
  5	import { Exchange, FailedTurn, PendingTurn, palette, smallButton } from './ConversationTurns';
  6	
  7	export type HistoryLoadState = 'loading' | 'loaded' | 'error';
  8	
  9	interface Props {
 10	  history: QAHistory[];
 11	  loadState: HistoryLoadState;
 12	  pendingQuestion: string | null;
 13	  /** Failed questions, oldest first. Each stays until it is retried or dismissed. */
 14	  askErrors: AskError[];
 15	  documentCount: number;
 16	  selectedDocId: string | null;
 17	  /** Resolves to false when the cited document no longer exists. */
 18	  onOpenCitation: (citation: Citation) => Promise<boolean>;
 19	  onRetry: (error: AskError) => void;
 20	  onDismissError: (error: AskError) => void;
 21	  onReloadHistory: () => void;
 22	  /** Resolves to false when clearing failed. */
 23	  onClear: () => Promise<boolean>;
 24	}
 25	
 26	export function ConversationView({
 27	  history,
 28	  loadState,
 29	  pendingQuestion,
 30	  askErrors,
 31	  documentCount,
 32	  selectedDocId,
 33	  onOpenCitation,
 34	  onRetry,
 35	  onDismissError,
 36	  onReloadHistory,
 37	  onClear,
 38	}: Props) {
 39	  const scrollRef = useRef<HTMLDivElement>(null);
 40	  const clearButtonRef = useRef<HTMLButtonElement>(null);
 41	  const cancelButtonRef = useRef<HTMLButtonElement>(null);
 42	  const headingRef = useRef<HTMLHeadingElement>(null);
 43	  const [confirmingClear, setConfirmingClear] = useState(false);
 44	  const [clearFailed, setClearFailed] = useState(false);
 45	  const [unavailable, setUnavailable] = useState<Set<string>>(() => new Set());
 46	
 47	  const busy = pendingQuestion !== null;
 48	
 49	  // Keep the newest exchange in view whenever a turn is added, resolved or fails.
 50	  useEffect(() => {
 51	    const el = scrollRef.current;
 52	    if (el) el.scrollTop = el.scrollHeight;
 53	  }, [history.length, pendingQuestion, askErrors.length, loadState]);
 54	
 55	  // Citation indices shift when history is cleared; drop stale "unavailable" marks.
 56	  useEffect(() => {
 57	    if (history.length === 0) setUnavailable(new Set());
 58	  }, [history.length]);
 59	
 60	  useEffect(() => {
 61	    if (confirmingClear) cancelButtonRef.current?.focus();
 62	  }, [confirmingClear]);
 63	
 64	  const handleActivate = async (citation: Citation, key: string) => {
 65	    const found = await onOpenCitation(citation);
 66	    setUnavailable(prev => {
 67	      if (found === !prev.has(key)) return prev;
 68	      const next = new Set(prev);
 69	      if (found) next.delete(key);
 70	      else next.add(key);
 71	      return next;
 72	    });
 73	  };
 74	
 75	  const cancelClear = () => {
 76	    setConfirmingClear(false);
 77	    // Return focus to the control that opened the confirmation.
 78	    requestAnimationFrame(() => clearButtonRef.current?.focus());
 79	  };
 80	
 81	  const confirmClear = async () => {
 82	    const ok = await onClear();
 83	    setClearFailed(!ok);
 84	    setConfirmingClear(false);
 85	    // The focused button is about to unmount; move focus somewhere meaningful instead of <body>.
 86	    requestAnimationFrame(() => {
 87	      if (ok) headingRef.current?.focus();
 88	      else clearButtonRef.current?.focus();
 89	    });
 90	  };
 91	
 92	  const handleConfirmKeyDown = (e: KeyboardEvent<HTMLDivElement>) => {
 93	    if (e.key === 'Escape') {
 94	      e.preventDefault();
 95	      e.stopPropagation();
 96	      cancelClear();
 97	    }
 98	  };
 99	
100	  // In the load-error state Clear is the in-app way to recover from an unreadable history file.
101	  const canClear = (history.length > 0 || loadState === 'error') && !busy;
102	  const confirmMessage = loadState === 'error'
103	    ? 'Replace the unreadable conversation history with an empty one? This cannot be undone.'
104	    : `Delete all ${history.length} ${history.length === 1 ? 'exchange' : 'exchanges'}? This cannot be undone.`;
105	
106	  const showEmpty = loadState === 'loaded' && history.length === 0 && !busy && askErrors.length === 0;
107	
108	  return (
109	    <section
110	      aria-labelledby="conversation-heading"
111	      style={{ flex: 1, display: 'flex', flexDirection: 'column', minHeight: 0 }}
112	    >
113	      <div style={{
114	        display: 'flex',
115	        alignItems: 'center',
116	        justifyContent: 'space-between',
117	        flexWrap: 'wrap',
118	        gap: '8px',
119	        padding: '8px 20px',
120	        background: palette.panel,
121	        borderBottom: `1px solid ${palette.border}`,
122	      }}>
123	        <h2 id="conversation-heading" ref={headingRef} tabIndex={-1} style={{ fontSize: '13px', fontWeight: 600 }}>
124	          Conversation
125	          <span style={{ color: palette.muted, fontWeight: 400 }}>
126	            {' '}({history.length} {history.length === 1 ? 'exchange' : 'exchanges'})
127	          </span>
128	        </h2>
129	        {confirmingClear ? (
130	          <div
131	            role="group"
132	            aria-label="Confirm clearing the conversation"
133	            onKeyDown={handleConfirmKeyDown}
134	            style={{ display: 'flex', alignItems: 'center', gap: '8px', fontSize: '12px' }}
135	          >
136	            <span>{confirmMessage}</span>
137	            <button ref={cancelButtonRef} type="button" onClick={cancelClear} style={smallButton}>
138	              Cancel
139	            </button>
140	            <button
141	              type="button"
142	              onClick={confirmClear}
143	              style={{ ...smallButton, background: palette.accent, border: 'none', color: '#fff' }}
144	            >
145	              Clear conversation
146	            </button>
147	          </div>
148	        ) : (
149	          <button
150	            ref={clearButtonRef}
151	            type="button"
152	            onClick={() => setConfirmingClear(true)}
153	            disabled={!canClear}
154	            style={{
155	              ...smallButton,
156	              opacity: canClear ? 1 : 0.5,
157	              cursor: canClear ? 'pointer' : 'default',
158	            }}
159	          >
160	            Clear
161	          </button>
162	        )}
163	      </div>
164	
165	      {clearFailed && (
166	        <div role="alert" style={{ padding: '6px 20px', fontSize: '12px', color: palette.error }}>
167	          Could not clear the conversation. Please try again.
168	        </div>
169	      )}
170	
171	      <div
172	        ref={scrollRef}
173	        style={{ flex: 1, overflowY: 'auto', overflowX: 'hidden', padding: '16px 20px' }}
174	      >
175	        {loadState === 'loading' && (
176	          <div style={{ color: '#666', textAlign: 'center', paddingTop: '24px', fontSize: '13px' }}>
177	            Loading conversation…
178	          </div>
179	        )}
180	
181	        {loadState === 'error' && (
182	          <div role="alert" style={{ color: palette.error, textAlign: 'center', paddingTop: '24px', fontSize: '13px' }}>
183	            Could not load the conversation history.{' '}
184	            <button type="button" onClick={onReloadHistory} style={smallButton}>Try again</button>
185	            <div style={{ marginTop: '8px', color: palette.muted }}>
186	              If this keeps failing, the saved history may be damaged. Use Clear above to start a new, empty conversation.
187	            </div>
188	          </div>
189	        )}
190	
191	        {showEmpty && (
192	          <div style={{ color: '#888', textAlign: 'center', paddingTop: '32px', fontSize: '13px', lineHeight: 1.6 }}>
193	            <div style={{ fontSize: '15px', color: palette.text, marginBottom: '6px' }}>No questions yet</div>
194	            Ask a question below. Each answer will appear here with the sources it cites,
195	            <br />
196	            and the conversation is kept between sessions.
197	            {documentCount === 0 && (
198	              <div style={{ marginTop: '8px', color: palette.muted }}>
199	                Tip: import and index documents first so answers can cite them.
200	              </div>
201	            )}
202	          </div>
203	        )}
204	
205	        <div role="log" aria-live="polite" aria-label="Conversation messages">
206	          <ol style={{ listStyle: 'none', display: 'flex', flexDirection: 'column', gap: '20px' }}>
207	            {history.map((item, i) => (
208	              <li key={`${item.response.timestamp}-${i}`}>
209	                <Exchange
210	                  item={item}
211	                  index={i}
212	                  total={history.length}
213	                  isLatest={i === history.length - 1}
214	                  selectedDocId={selectedDocId}
215	                  unavailable={unavailable}
216	                  onActivate={handleActivate}
217	                />
218	              </li>
219	            ))}
220	
221	            {askErrors.map(error => (
222	              <li key={`error-${error.id}`}>
223	                <FailedTurn error={error} busy={busy} onRetry={onRetry} onDismiss={onDismissError} />
224	              </li>
225	            ))}
226	
227	            {pendingQuestion !== null && (
228	              <li key="pending">
229	                <PendingTurn question={pendingQuestion} />
230	              </li>
231	            )}
232	          </ol>
233	        </div>
234	      </div>
235	    </section>
236	  );
237	}
  1	import type { CSSProperties } from 'react';
  2	import { Citation, QAHistory } from '../../shared/types';
  3	import { AskError, describeConfidence, formatTimestamp } from './conversation-format';
  4	
  5	/** DOM id of the newest exchange; focused by the "Jump to latest answer" control. */
  6	export const LATEST_EXCHANGE_ID = 'latest-exchange';
  7	
  8	export const palette = {
  9	  panel: '#16213e',
 10	  card: '#1a1a3e',
 11	  border: '#0f3460',
 12	  accent: '#533483',
 13	  text: '#e0e0e0',
 14	  muted: '#8888bb',
 15	  error: '#d9534f',
 16	};
 17	
 18	export const smallButton: CSSProperties = {
 19	  padding: '4px 10px',
 20	  background: palette.border,
 21	  color: palette.text,
 22	  border: '1px solid #1a1a4e',
 23	  borderRadius: '4px',
 24	  cursor: 'pointer',
 25	  fontSize: '12px',
 26	};
 27	
 28	export const turnLabel: CSSProperties = {
 29	  fontSize: '11px',
 30	  fontWeight: 600,
 31	  textTransform: 'uppercase',
 32	  letterSpacing: '0.05em',
 33	  color: palette.muted,
 34	  marginBottom: '4px',
 35	};
 36	
 37	export const textBlock: CSSProperties = {
 38	  fontSize: '14px',
 39	  lineHeight: 1.6,
 40	  whiteSpace: 'pre-wrap',
 41	  overflowWrap: 'anywhere',
 42	};
 43	
 44	function citationKey(exchangeIndex: number, citationIndex: number): string {
 45	  return `${exchangeIndex}:${citationIndex}`;
 46	}
 47	
 48	export function UserTurn({ question }: { question: string }) {
 49	  return (
 50	    <div style={{
 51	      alignSelf: 'flex-end',
 52	      maxWidth: '85%',
 53	      minWidth: 0,
 54	      padding: '10px 14px',
 55	      background: palette.border,
 56	      borderRadius: '8px 8px 2px 8px',
 57	    }}>
 58	      <div style={turnLabel}>You</div>
 59	      <div style={textBlock}>{question}</div>
 60	    </div>
 61	  );
 62	}
 63	
 64	function CitationList({
 65	  citations,
 66	  exchangeIndex,
 67	  selectedDocId,
 68	  unavailable,
 69	  onActivate,
 70	}: {
 71	  citations: Citation[];
 72	  exchangeIndex: number;
 73	  selectedDocId: string | null;
 74	  unavailable: Set<string>;
 75	  onActivate: (citation: Citation, key: string) => void;
 76	}) {
 77	  if (citations.length === 0) {
 78	    return (
 79	      <div style={{ marginTop: '10px', fontSize: '12px', color: palette.muted, fontStyle: 'italic' }}>
 80	        No sources cited.
 81	      </div>
 82	    );
 83	  }
 84	
 85	  return (
 86	    <div style={{ marginTop: '12px' }}>
 87	      <div style={{ ...turnLabel, marginBottom: '6px' }}>Sources ({citations.length})</div>
 88	      <ul style={{ listStyle: 'none', display: 'flex', flexDirection: 'column', gap: '6px' }}>
 89	        {citations.map((c, i) => {
 90	          const key = citationKey(exchangeIndex, i);
 91	          const isMissing = unavailable.has(key);
 92	          const isSelected = selectedDocId === c.documentId;
 93	          return (
 94	            <li key={key}>
 95	              <button
 96	                type="button"
 97	                onClick={() => onActivate(c, key)}
 98	                title={`Open "${c.documentTitle}"`}
 99	                style={{
100	                  display: 'block',
101	                  width: '100%',
102	                  textAlign: 'left',
103	                  padding: '8px 10px',
104	                  background: isSelected ? palette.border : palette.panel,
105	                  color: palette.text,
106	                  border: `1px solid ${palette.border}`,
107	                  borderLeft: `3px solid ${palette.accent}`,
108	                  borderRadius: '4px',
109	                  cursor: 'pointer',
110	                  fontSize: '12px',
111	                  lineHeight: 1.5,
112	                  overflowWrap: 'anywhere',
113	                }}
114	              >
115	                <span style={{ fontWeight: 600 }}>{c.documentTitle}</span>
116	                <span style={{ color: palette.muted }}> · chunk {c.chunkIndex}</span>
117	                {isSelected && <span style={{ color: palette.muted }}> · open</span>}
118	                <span style={{ display: 'block', marginTop: '2px', color: '#c0c0e0', whiteSpace: 'pre-wrap' }}>
119	                  “{c.excerpt}”
120	                </span>
121	                {isMissing && (
122	                  <span style={{ display: 'block', marginTop: '4px', color: palette.error }}>
123	                    This document is no longer available.
124	                  </span>
125	                )}
126	              </button>
127	            </li>
128	          );
129	        })}
130	      </ul>
131	    </div>
132	  );
133	}
134	
135	export function Exchange({
136	  item,
137	  index,
138	  total,
139	  isLatest,
140	  selectedDocId,
141	  unavailable,
142	  onActivate,
143	}: {
144	  item: QAHistory;
145	  index: number;
146	  total: number;
147	  /** The newest exchange is the target of the "Jump to latest answer" control. */
148	  isLatest: boolean;
149	  selectedDocId: string | null;
150	  unavailable: Set<string>;
151	  onActivate: (citation: Citation, key: string) => void;
152	}) {
153	  const { response } = item;
154	  const confidence = describeConfidence(response.confidence);
155	  return (
156	    <article
157	      id={isLatest ? LATEST_EXCHANGE_ID : undefined}
158	      tabIndex={isLatest ? -1 : undefined}
159	      aria-label={`Exchange ${index + 1} of ${total}`}
160	      style={{ display: 'flex', flexDirection: 'column', gap: '8px' }}
161	    >
162	      <UserTurn question={item.question} />
163	      <div style={{
164	        alignSelf: 'stretch',
165	        minWidth: 0,
166	        padding: '12px 14px',
167	        background: palette.card,
168	        border: `1px solid ${palette.border}`,
169	        borderRadius: '8px 8px 8px 2px',
170	      }}>
171	        <div style={{ display: 'flex', flexWrap: 'wrap', gap: '4px 12px', alignItems: 'baseline', ...turnLabel }}>
172	          <span>Assistant</span>
173	          <time
174	            dateTime={response.timestamp}
175	            style={{ textTransform: 'none', letterSpacing: 0, fontWeight: 400 }}
176	          >
177	            {formatTimestamp(response.timestamp)}
178	          </time>
179	          <span style={{ textTransform: 'none', letterSpacing: 0, fontWeight: 400 }}>
180	            <span
181	              aria-hidden="true"
182	              style={{
183	                display: 'inline-block',
184	                width: '40px',
185	                height: '6px',
186	                marginRight: '6px',
187	                background: palette.border,
188	                borderRadius: '3px',
189	                overflow: 'hidden',
190	                verticalAlign: 'middle',
191	              }}
192	            >
193	              <span style={{
194	                display: 'block',
195	                width: `${confidence.percent}%`,
196	                height: '100%',
197	                background: palette.accent,
198	              }} />
199	            </span>
200	            Confidence: {confidence.level} ({confidence.percent}%)
201	          </span>
202	        </div>
203	        <div style={textBlock}>{response.answer}</div>
204	        <CitationList
205	          citations={response.citations}
206	          exchangeIndex={index}
207	          selectedDocId={selectedDocId}
208	          unavailable={unavailable}
209	          onActivate={onActivate}
210	        />
211	      </div>
212	    </article>
213	  );
214	}
215	
216	export function PendingTurn({ question }: { question: string }) {
217	  return (
218	    <article aria-label="Question awaiting an answer" aria-busy="true" style={{ display: 'flex', flexDirection: 'column', gap: '8px' }}>
219	      <UserTurn question={question} />
220	      <div style={{
221	        padding: '12px 14px',
222	        background: palette.card,
223	        border: `1px dashed ${palette.border}`,
224	        borderRadius: '8px 8px 8px 2px',
225	      }}>
226	        <div style={turnLabel}>Assistant</div>
227	        <div style={{ ...textBlock, color: palette.muted, fontStyle: 'italic' }}>Answering…</div>
228	      </div>
229	    </article>
230	  );
231	}
232	
233	export function FailedTurn({
234	  error,
235	  busy,
236	  onRetry,
237	  onDismiss,
238	}: {
239	  error: AskError;
240	  busy: boolean;
241	  onRetry: (error: AskError) => void;
242	  onDismiss: (error: AskError) => void;
243	}) {
244	  return (
245	    <article aria-label="Question that could not be answered" style={{ display: 'flex', flexDirection: 'column', gap: '8px' }}>
246	      <UserTurn question={error.question} />
247	      <div role="alert" style={{
248	        padding: '12px 14px',
249	        background: palette.card,
250	        border: `1px solid ${palette.error}`,
251	        borderRadius: '8px 8px 8px 2px',
252	      }}>
253	        <div style={{ ...turnLabel, color: palette.error }}>Not answered</div>
254	        <div style={{ fontSize: '13px', lineHeight: 1.5 }}>
255	          Something went wrong and this question could not be answered. Your question is kept here so you can try it again.
256	        </div>
257	        <details style={{ fontSize: '12px', color: palette.muted, marginTop: '6px' }}>
258	          <summary style={{ cursor: 'pointer' }}>Technical details</summary>
259	          <div style={{ marginTop: '4px', overflowWrap: 'anywhere' }}>{error.message}</div>
260	        </details>
261	        <div style={{ display: 'flex', gap: '8px', marginTop: '10px' }}>
262	          <button
263	            type="button"
264	            onClick={() => onRetry(error)}
265	            disabled={busy}
266	            style={{ ...smallButton, background: palette.accent, border: 'none', color: '#fff', opacity: busy ? 0.5 : 1 }}
267	          >
268	            Retry
269	          </button>
270	          <button type="button" onClick={() => onDismiss(error)} style={smallButton}>
271	            Dismiss
272	          </button>
273	        </div>
274	      </div>
275	    </article>
276	  );
277	}
  1	/**
  2	 * Display-only formatting helpers for the conversation view.
  3	 * Pure functions so they can be unit-tested without a DOM.
  4	 */
  5	
  6	/** Formats an ISO timestamp as a readable local date and time, e.g. "Nov 15, 2026, 10:42 PM". */
  7	export function formatTimestamp(iso: string, locale?: string): string {
  8	  const date = new Date(iso);
  9	  if (Number.isNaN(date.getTime())) return 'Unknown time';
 10	  return date.toLocaleString(locale, { dateStyle: 'medium', timeStyle: 'short' });
 11	}
 12	
 13	export type ConfidenceLevel = 'High' | 'Medium' | 'Low';
 14	
 15	/** Maps a 0..1 confidence score to a percentage and a text label (never colour alone). */
 16	export function describeConfidence(confidence: number): { percent: number; level: ConfidenceLevel } {
 17	  const clamped = Number.isFinite(confidence) ? Math.min(1, Math.max(0, confidence)) : 0;
 18	  const percent = Math.round(clamped * 100);
 19	  const level: ConfidenceLevel = clamped >= 0.7 ? 'High' : clamped >= 0.4 ? 'Medium' : 'Low';
 20	  return { percent, level };
 21	}
 22	
 23	/** Turns an IPC rejection into a short, user-facing message. */
 24	export function describeAskError(err: unknown): string {
 25	  const raw = err instanceof Error ? err.message : String(err);
 26	  // Electron prefixes rejections with "Error invoking remote method '<channel>': ".
 27	  const cleaned = raw.replace(/^Error invoking remote method '[^']+':\s*/, '').trim();
 28	  return cleaned || 'Unknown error';
 29	}
 30	
 31	/** A question whose answer failed. Kept until the user retries or dismisses it. */
 32	export interface AskError {
 33	  id: number;
 34	  question: string;
 35	  message: string;
 36	}
 37	
 38	/** Appends a failure. Earlier failures are never overwritten. */
 39	export function addAskError(errors: AskError[], error: AskError): AskError[] {
 40	  return [...errors, error];
 41	}
 42	
 43	/** Removes one failure (on retry or dismiss); other failures are kept. */
 44	export function removeAskError(errors: AskError[], id: number): AskError[] {
 45	  return errors.some(e => e.id === id) ? errors.filter(e => e.id !== id) : errors;
 46	}

