  6	
  7	export type HistoryLoadState = 'loading' | 'loaded' | 'error';
  8	
  9	interface Props {
 10	  history: QAHistory[];
 11	  loadState: HistoryLoadState;
 12	  pendingQuestion: string | null;
 13	  /** Failed questions, oldest first. Each stays until it is retried or dismissed. */
 14	  askErrors: AskError[];
 15	  documentCount: number;
 16	  selectedDocId: string | null;
 17	  /** Resolves to false when the cited document no longer exists. */
 18	  onOpenCitation: (citation: Citation) => Promise<boolean>;
 19	  onRetry: (error: AskError) => void;
 20	  onDismissError: (error: AskError) => void;
 21	  onReloadHistory: () => void;
