100	  // In the load-error state Clear is the in-app way to recover from an unreadable history file.
101	  const canClear = (history.length > 0 || loadState === 'error') && !busy;
102	  const confirmMessage = loadState === 'error'
103	    ? 'Replace the unreadable conversation history with an empty one? This cannot be undone.'
104	    : `Delete all ${history.length} ${history.length === 1 ? 'exchange' : 'exchanges'}? This cannot be undone.`;
105	
106	  const showEmpty = loadState === 'loaded' && history.length === 0 && !busy && askErrors.length === 0;
107	
108	  return (
109	    <section
110	      aria-labelledby="conversation-heading"
111	      style={{ flex: 1, display: 'flex', flexDirection: 'column', minHeight: 0 }}
112	    >
113	      <div style={{
114	        display: 'flex',
115	        alignItems: 'center',
116	        justifyContent: 'space-between',
117	        flexWrap: 'wrap',
118	        gap: '8px',
