121	        borderBottom: `1px solid ${palette.border}`,
122	      }}>
123	        <h2 id="conversation-heading" ref={headingRef} tabIndex={-1} style={{ fontSize: '13px', fontWeight: 600 }}>
124	          Conversation
125	          <span style={{ color: palette.muted, fontWeight: 400 }}>
126	            {' '}({history.length} {history.length === 1 ? 'exchange' : 'exchanges'})
127	          </span>
128	        </h2>
129	        {confirmingClear ? (
130	          <div
131	            role="group"
132	            aria-label="Confirm clearing the conversation"
133	            onKeyDown={handleConfirmKeyDown}
