135	          >
136	            <span>{confirmMessage}</span>
137	            <button ref={cancelButtonRef} type="button" onClick={cancelClear} style={smallButton}>
138	              Cancel
139	            </button>
140	            <button
141	              type="button"
142	              onClick={confirmClear}
143	              style={{ ...smallButton, background: palette.accent, border: 'none', color: '#fff' }}
144	            >
145	              Clear conversation
146	            </button>
147	          </div>
148	        ) : (
149	          <button
150	            ref={clearButtonRef}
151	            type="button"
152	            onClick={() => setConfirmingClear(true)}
153	            disabled={!canClear}
154	            style={{
155	              ...smallButton,
156	              opacity: canClear ? 1 : 0.5,
157	              cursor: canClear ? 'pointer' : 'default',
158	            }}
159	          >
160	            Clear
161	          </button>
162	        )}
163	      </div>
164	
165	      {clearFailed && (
166	        <div role="alert" style={{ padding: '6px 20px', fontSize: '12px', color: palette.error }}>
167	          Could not clear the conversation. Please try again.
168	        </div>
169	      )}
170	
171	      <div
172	        ref={scrollRef}
173	        style={{ flex: 1, overflowY: 'auto', overflowX: 'hidden', padding: '16px 20px' }}
174	      >
175	        {loadState === 'loading' && (
