  6	/** Formats an ISO timestamp as a readable local date and time, e.g. "Nov 15, 2026, 10:42 PM". */
  7	export function formatTimestamp(iso: string, locale?: string): string {
  8	  const date = new Date(iso);
  9	  if (Number.isNaN(date.getTime())) return 'Unknown time';
 10	  return date.toLocaleString(locale, { dateStyle: 'medium', timeStyle: 'short' });
 11	}
 12	
 13	export type ConfidenceLevel = 'High' | 'Medium' | 'Low';
 14	
 15	/** Maps a 0..1 confidence score to a percentage and a text label (never colour alone). */
 16	export function describeConfidence(confidence: number): { percent: number; level: ConfidenceLevel } {
 17	  const clamped = Number.isFinite(confidence) ? Math.min(1, Math.max(0, confidence)) : 0;
 18	  const percent = Math.round(clamped * 100);
 19	  const level: ConfidenceLevel = clamped >= 0.7 ? 'High' : clamped >= 0.4 ? 'Medium' : 'Low';
 20	  return { percent, level };
 21	}
 22	
 23	/** Turns an IPC rejection into a short, user-facing message. */
 24	export function describeAskError(err: unknown): string {
 25	  const raw = err instanceof Error ? err.message : String(err);
 26	  // Electron prefixes rejections with "Error invoking remote method '<channel>': ".
 27	  const cleaned = raw.replace(/^Error invoking remote method '[^']+':\s*/, '').trim();
 28	  return cleaned || 'Unknown error';
 29	}
