 31	/** A question whose answer failed. Kept until the user retries or dismisses it. */
 32	export interface AskError {
 33	  id: number;
 34	  question: string;
 35	  message: string;
 36	}
 37	
 38	/** Appends a failure. Earlier failures are never overwritten. */
 39	export function addAskError(errors: AskError[], error: AskError): AskError[] {
 40	  return [...errors, error];
 41	}
 42	
 43	/** Removes one failure (on retry or dismiss); other failures are kept. */
 44	export function removeAskError(errors: AskError[], id: number): AskError[] {
 45	  return errors.some(e => e.id === id) ? errors.filter(e => e.id !== id) : errors;
 46	}

