 13	  GET_DOCUMENT: 'documents:get',
 14	  DELETE_DOCUMENT: 'documents:delete',
 15	  START_INDEXING: 'indexing:start',
 16	  GET_INDEXING_STATUS: 'indexing:status',
 17	  GET_CHUNKS: 'indexing:chunks',
 18	  ASK_QUESTION: 'qa:ask',
 19	  GET_HISTORY: 'qa:history',
 20	  CLEAR_HISTORY: 'qa:clear-history',
 21	  GET_CONVERSATION: 'conversation:get',
 22	  GET_STATUS: 'app:status',
 23	};
