 25	const api = {
 26	  documents: {
 27	    list: () => ipcRenderer.invoke(IPC_CHANNELS.LIST_DOCUMENTS),
 28	    import: (filePath: string) => ipcRenderer.invoke(IPC_CHANNELS.IMPORT_DOCUMENT, filePath),
 29	    get: (id: string) => ipcRenderer.invoke(IPC_CHANNELS.GET_DOCUMENT, id),
 30	    delete: (id: string) => ipcRenderer.invoke(IPC_CHANNELS.DELETE_DOCUMENT, id),
