 27	  const refreshDocuments = useCallback(async () => {
 28	    try {
 29	      const docs = await window.knowledgeBase.documents.list();
 30	      setDocuments(docs);
 31	      const status = await window.knowledgeBase.indexing.status();
 32	      setAppStatus(status);
 33	    } catch (err) {
 34	      console.error('Failed to refresh documents:', err);
 35	    }
 36	  }, []);
 37	
 38	  /** Loads the persisted conversation. Returns null if it could not be read. */
 39	  const loadHistory = useCallback(async (): Promise<QAHistory[] | null> => {
 40	    try {
 41	      const history = await window.knowledgeBase.conversation.get();
 42	      setConversationHistory(history);
 43	      setHistoryLoadState('loaded');
 44	      return history;
 45	    } catch {
 46	      // Keep whatever is already on screen; only report an error if nothing was ever loaded.
 47	      setHistoryLoadState(prev => (prev === 'loading' ? 'error' : prev));
 48	      return null;
 49	    }
 50	  }, []);
 51	
 52	  useEffect(() => {
 53	    refreshDocuments();
 54	    loadHistory();
 55	  }, [refreshDocuments, loadHistory]);
 56	
 57	  const handleImport = useCallback(async () => {
 58	    console.log('Import triggered - use window.knowledgeBase.documents.import(filePath)');
 59	  }, []);
 60	
 61	  const handleSelectDocument = useCallback((doc: Document) => {
 62	    setSelectedDoc(doc);
 63	  }, []);
 64	
 65	  /** Asks a question. `retryOf` is the failed entry being retried; it becomes the pending turn. */
 66	  const handleAskQuestion = useCallback(async (question: string, retryOf?: AskError) => {
 67	    if (askInFlight.current) return;
 68	    askInFlight.current = true;
 69	    if (retryOf) setAskErrors(prev => removeAskError(prev, retryOf.id));
 70	    setPendingQuestion(question);
 71	    try {
 72	      const response = await window.knowledgeBase.qa.ask(question);
 73	      // The service persists the exchange before replying, so the reloaded history already
 74	      // contains it. Replace the optimistic turn with the persisted one in the same synchronous
 75	      // block so no render shows the question twice.
 76	      let persisted: QAHistory[] | null = null;
 77	      try {
 78	        persisted = await window.knowledgeBase.conversation.get();
 79	      } catch {
 80	        persisted = null;
 81	      }
 82	      if (persisted) {
 83	        setConversationHistory(persisted);
 84	        setHistoryLoadState('loaded');
 85	      } else {
 86	        setConversationHistory(prev => [...prev, { question, response }]);
 87	      }
 88	      setPendingQuestion(null);
 89	    } catch (err) {
 90	      const failure: AskError = { id: nextErrorId.current++, question, message: describeAskError(err) };
 91	      setAskErrors(prev => addAskError(prev, failure));
 92	      setPendingQuestion(null);
 93	    } finally {
 94	      askInFlight.current = false;
 95	    }
 96	  }, []);
 97	
 98	  const handleOpenCitation = useCallback(async (citation: Citation): Promise<boolean> => {
 99	    // Always ask main: the cached document list may be stale in either direction (a cited document
100	    // may have been deleted or added since the last refresh), and trusting it opens a "ghost" detail.
101	    let doc: Document | null = null;
102	    try {
103	      doc = await window.knowledgeBase.documents.get(citation.documentId);
104	    } catch {
105	      doc = null;
106	    }
107	    const isStale = doc
108	      ? !documents.some(d => d.id === citation.documentId)
109	      : documents.some(d => d.id === citation.documentId);
110	    if (isStale) refreshDocuments();
111	    if (!doc) {
112	      setSelectedDoc(prev => (prev?.id === citation.documentId ? null : prev));
113	      return false;
114	    }
115	    setSelectedDoc(doc);
116	    return true;
117	  }, [documents, refreshDocuments]);
118	
119	  const handleClearConversation = useCallback(async (): Promise<boolean> => {
120	    try {
121	      await window.knowledgeBase.qa.clearHistory();
122	      setAskErrors([]);
123	      const reloaded = await loadHistory();
124	      if (reloaded === null) setConversationHistory([]);
125	      return true;
126	    } catch {
127	      return false;
128	    }
129	  }, [loadHistory]);
130	
131	  return (
132	    <div style={{ display: 'flex', flexDirection: 'column', height: '100vh' }}>
133	      <header style={{
134	        padding: '12px 20px',
135	        background: '#16213e',
136	        borderBottom: '1px solid #0f3460',
137	        display: 'flex',
138	        alignItems: 'center',
139	        justifyContent: 'space-between',
140	      }}>
141	        <h1 style={{ fontSize: '18px', fontWeight: 600 }}>Knowledge Base</h1>
142	        <button
143	          onClick={refreshDocuments}
144	          style={{
145	            padding: '6px 14px',
146	            background: '#0f3460',
147	            color: '#e0e0e0',
148	            border: '1px solid #1a1a4e',
149	            borderRadius: '4px',
150	            cursor: 'pointer',
151	            fontSize: '13px',
152	          }}
153	        >
154	          Refresh
155	        </button>
156	      </header>
157	
158	      <div style={{ display: 'flex', flex: 1, overflow: 'hidden' }}>
159	        {/* Left panel: document list */}
160	        <div style={{
161	          width: '280px',
162	          flexShrink: 0,
163	          borderRight: '1px solid #0f3460',
164	          display: 'flex',
165	          flexDirection: 'column',
166	          background: '#16213e',
167	        }}>
168	          <div style={{
169	            padding: '8px 16px',
170	            display: 'flex',
171	            alignItems: 'center',
172	            justifyContent: 'space-between',
173	            borderBottom: '1px solid #0f3460',
174	          }}>
175	            <h2 style={{ fontSize: '12px', fontWeight: 500 }}>
176	              Documents ({documents.length})
177	            </h2>
178	            <button
179	              onClick={handleImport}
180	              style={{
181	                padding: '4px 10px',
182	                background: '#533483',
183	                color: '#fff',
184	                border: 'none',
185	                borderRadius: '3px',
186	                cursor: 'pointer',
187	                fontSize: '12px',
188	              }}
189	            >
190	              + Import
191	            </button>
192	          </div>
193	          <DocumentList
194	            documents={documents}
195	            onSelect={handleSelectDocument}
196	            selectedId={selectedDoc?.id ?? null}
197	          />
198	        </div>
199	
200	        {/* Right panel: selected document (if any) above the conversation and question input */}
201	        <main style={{ flex: 1, minWidth: 0, display: 'flex', flexDirection: 'column', overflow: 'hidden' }}>
202	          {selectedDoc && (
203	            <section
204	              aria-label="Selected document"
205	              style={{
206	                flexShrink: 0,
207	                maxHeight: '40%',
208	                overflow: 'auto',
209	                padding: '16px 20px',
210	                borderBottom: '1px solid #0f3460',
211	                position: 'relative',
212	              }}
213	            >
214	              <button
215	                type="button"
216	                onClick={() => setSelectedDoc(null)}
217	                aria-label="Close document"
218	                style={{
219	                  float: 'right',
220	                  padding: '4px 10px',
221	                  background: 'transparent',
222	                  color: '#8888bb',
223	                  border: '1px solid #0f3460',
224	                  borderRadius: '4px',
225	                  cursor: 'pointer',
226	                  fontSize: '12px',
227	                }}
228	              >
229	                Close
230	              </button>
231	              <DocumentDetail key={selectedDoc.id} document={selectedDoc} />
232	            </section>
233	          )}
234	
235	          <ConversationView
236	            history={conversationHistory}
237	            loadState={historyLoadState}
238	            pendingQuestion={pendingQuestion}
239	            askErrors={askErrors}
240	            documentCount={documents.length}
241	            selectedDocId={selectedDoc?.id ?? null}
242	            onOpenCitation={handleOpenCitation}
243	            onRetry={error => handleAskQuestion(error.question, error)}
244	            onDismissError={error => setAskErrors(prev => removeAskError(prev, error.id))}
245	            onReloadHistory={loadHistory}
246	            onClear={handleClearConversation}
247	          />
248	
249	          <QuestionPanel
250	            onAsk={handleAskQuestion}
251	            busy={pendingQuestion !== null}
252	            canJumpToLatest={conversationHistory.length > 0}
253	          />
254	        </main>
255	      </div>
256	
257	      <StatusBar status={appStatus} />
258	    </div>
259	  );
260	}

